//Keeping it simple and graceful.

let m, center, speed, offsetInc
let colors = ["#2a274a", "#3d3829", "#729880", "#d0d074", "#719c67", "#70732b", "#a6690e"]
let offsetter = 0

function setup() {
	m = max(windowWidth, windowHeight)
	createCanvas(m, m);
	center = createVector(width * 0.5, height * 0.5)
	offsetInc = TAU / 7
	noStroke()
}

function draw() {
	background("#a53c0b")
	offsetter = 0
	speed = frameCount * 0.01
	for (let i = 0; i < colors.length; i++) {
		fill(colors[i])
		let sizer = map(i, 0, colors.length, m * 0.2, m * 0.175)
		body(center, 0, sizer, 0, 1)
	}
}

function body(fulcrum, orbitR, s, offset, depth) {
	rspeed = speed * depth
	let newPos = createVector(fulcrum.x + (cos(offset + rspeed) * orbitR), fulcrum.y + (sin(offset + rspeed) * orbitR))
	circle(newPos.x, newPos.y, s)
	if (depth < 6) {
		offsetter += offsetInc
		let newS = s * 0.5
		body(newPos, newS * 2.75, newS, offsetter, depth + 1)
	}
}
